quests[38141] = { id = 38141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 100-109 H" }
quests[38142] = { id = 38142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruidin der Klaue", description = "Nahe des südlichen Waldrands findet Ihr die Höhle der Schläfer.\n\nAn diesem Ort kommen die Erzdruidin Koda Stahlklaue und ihre eifrigen Schüler ihrer heiligen Pflicht nach, den Smaragdgrünen Traum zu beobachten.\n\nFindet die Schülerin Rylissa Bärensang im Stahlklauental und informiert sie über die Krise im Hain des Cenarius.", sourceObjective = "Sucht das Stahlklauental.", completion = "Der Wald flüstert schon von Malfurions Rückkehr. Es gibt nur wenige unter uns, die nicht von seinen Taten gehört haben.\n\nDie Bäume sagen auch, dass ein Gefährte namens {name} mit ihm reist. Seid Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[38143] = { id = 38143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erwachen der Erzdruidin", description = "Jetzt müssen wir uns darauf konzentrieren, Erzdruidin Koda Stahlklaue aufzuwecken.\n\nSie und die anderen Druiden ruhen in der Höhle der Schläfer im Süden.\n\nDa die Furbolgs ausgeschaltet sind, können wir jetzt sicher zum Eingang gelangen.\n\nGeht und weckt die Erzdruidin. Ich bete zu Elune, dass es noch nicht zu spät ist.", sourceObjective = "Weckt die Erzdruidin der Klaue auf.", completion = "<Die tiefen Atemzüge der Erzdruidin sind in der ganzen Kammer zu hören.>", sourceObjectiveStatus = "unverified-source-field" }
quests[38144] = { id = 38144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen in der Tiefe", description = "Irgendetwas oder irgendjemand wollte, dass wir nie wieder aufwachen. Ich kann diese finstere Präsenz noch immer in dieser Höhle spüren.\n\n<Koda benötigt einen Augenblick, um sich aufzurichten.>\n\nMein Körper ist noch schwach vom tiefen Schlaf.\n\nWenn Ihr uns helfen wollt, dann schaltet die Feinde in unserer Höhle aus.", sourceObjective = "Tötet 8 Eindringlinge der Schattenteufel.", completion = "Ausgezeichnet. Die Kammern sind gesäubert. Sehr beeindruckend, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[38145] = { id = 38145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende der Träume", description = "Malfurion Sturmgrimm... Diesen Namen habe ich schon seit Jahrhunderten nicht mehr gehört.\n\nEr war vielen von uns ein Lehrer. Wenn er mich sehen möchte, kann ich ihm dies nicht abschlagen.\n\nIch werde mich zum Hain des Cenarius begeben, aber zunächst müssen wir den Rest meines Klans aufwecken. Sie sind in einem Schlaf gefangen, aus dem sie aus eigener Kraft nicht erwachen können.\n\nEine mysteriöse Macht hat sich gegen uns gewandt.\n\nIch bin immer noch zu schwach vom langen Schlaf. Darum bitte ich Euch, <Fremder/Fremde>: Befreit die anderen aus ihren Träumen.", sourceObjective = "Erweckt 8 Druiden der Klaue.", progress = "Die Druiden der Klaue müssen aufwachen. Wir werden gebraucht.", completion = "Gut gemacht, Held. Zusammen mit den Anderen sind wir jetzt bereit, Malfurion zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38146] = { id = 38146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Perlen des Häuptlings", description = "Die mit Muscheln und Federn verzierten Zeremonienperlen werden vom Klanhäuptling getragen.\n\nVielleicht möchte der Älteste Sookh ja gern einen Blick darauf werfen.", sourceObjective = "Sprecht mit dem Ältesten Sookh beim Schwelhautdickicht.", completion = "Graw ist als Erster dem Wahnsinn erlegen und der Rest des Klans folgte ihm bald.\n\nDiese Perlen symbolisieren meinen Status als neuer Häuptling unseres Klans.\n\nIch danke Euch, Reisender. Ich werde mein Bestes geben, um unseren Klan wieder aufzubauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38147] = { id = 38147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umschlingende Träume", description = "Ich spüre mächtige Magie aus der Tiefe des Baus dringen.\n\nWas auch immer sich dort unten aufhält, webt einen mächtigen Zauber, der uns in unseren eigenen Träumen gefangen hält.\n\nIch bin noch zu schwach, aber Eure Fähigkeiten sind ziemlich beeindruckend, <Held/Heldin>. Ich kann verstehen, warum Malfurion sein Vertrauen in Euch setzt.\n\nGeht und eliminiert die Quelle dieser Magie.", sourceObjective = "Tötet Morphael.", progress = "Jemand hat uns in einem bösen Fluch gefangen gehalten.", completion = "In meinen Träumen habe ich den Anführer der Satyrn gesehen. Sein Gesicht kam mir bekannt vor, aber ich konnte es nicht deutlich erkennen.\n\nIch bete zu Elune, dass es noch nicht zu spät ist. Ich werde sofort zu Malfurion gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38148] = { id = 38148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Hain", description = "Jetzt wo mein Klan versammelt ist, werden wir zum Hain des Cenarius zurückkehren.\n\nSprecht mit Malfurion, wenn Ihr eintrefft. Wir werden den Grund für Cenarius' Krankheit herausfinden.", sourceObjective = "Kehrt zu Malfurion Sturmgrimm im Hain des Cenarius in Val'sharah zurück.", completion = "Wunderbar. Die Erzdruiden haben sich bereits versammelt.", sourceObjectiveStatus = "unverified-source-field" }
