quests[38199] = { id = 38199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht: Angriff auf die Säulen des Schicksals", description = "In den Anhöhen an den östlichen Grenzen der Spitzen von Arak sind weiterhin vereinzelte Truppen des Schattenmondklans aktiv, die von dort aus operieren.\n\nBodrick Grau ist deswegen besorgt, vor allem wegen ihrer Nähe zu unserer Garnison. Daher hat daher angeordnet, dass wir so bald wie möglich gegen diese Truppenkonzentrationen vorgehen.", sourceObjective = "Greift die Schattenmondorcs bei den Säulen des Schicksals im Schattenmondtal an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[38200] = { id = 38200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht: Angriff auf Skettis", description = "Wir erhalten vermehrt Berichte, dass Vogelmenschen aus dem Süden auf den Hauptstraßen Karawanen überfallen.\n\nDie Wachen in den Außenposten fordern, dass wir in Skettis an den Spitzen von Arak einen Gegenangriff gegen die Hauptstreitmacht der Jünger von Rukhmar führen.", sourceObjective = "Greift die Jünger von Rukhmar in Skettis an den Spitzen von Arak an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[38201] = { id = 38201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht: Angriff auf den Hafen von Shattrath", description = "Shattrath ist in die Hände der Sargereitruppen gefallen, die von dem verräterischen Exarchen Socrethar angeführt werden.\n\nDie Mitglieder der Sha'tarverteidigung haben um Unterstützung gegen die Truppen des Schattenrates im Ostteil der Stadt gebeten.", sourceObjective = "Greift die Sargereitruppen in Shattrath in Talador an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, Kommandant, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[38202] = { id = 38202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf das gorianische Übungsgelände", description = "Die Oger auf dem gorianischen Übungsgelände bilden Champions aus und wollen unsere Streitkräfte in Nagrand bekämpfen.\n\nWenn wir das Übungsgelände direkt angreifen, werden die Oger nicht genug Truppen haben, um gegen uns vorzugehen. Gleichzeitig kriegen sie eine Erinnerung, dass sie uns nicht als Feind wollen.", sourceObjective = "Greift die Oger auf dem gorianischen Übungsgelände in Nagrand an.", sourceObjectiveStatus = "unverified-source-field" }
quests[38203] = { id = 38203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weingut Challiane", description = "Bitte helft mir, <Fremder/Fremde>.\n\nZu Ehren von Königin Azshara habe ich ein Rezept für Nachtrosenwein entwickelt. Aber bevor ich ihn produzieren konnte, haben mir diese fiesen Weinhändler das Rezept abgenommen und mich weggesperrt.\n\nBitte holt dieses Rezept zurück, damit ich es Lady Challiane geben und die Gunst der Königin erlangen kann.", sourceObjective = "Sammelt die 3 Teile des Rezepts für Nachtrosenwein zusammen.", progress = "Habt Ihr die Zutaten für das Rezept gefunden?", completion = "Danke, Fremder! Ich danke Euch vielmals.\n\nIhr habt mehr für mich getan als jeder andere zuvor.\n\nLady Challiane hätte natürlich nur ihren Weinhändlern und nicht mir armen Kellermeister geglaubt.\n\nJetzt kann ich das Rezept verwenden, um erst ihre und dann die Gunst unserer geliebten Königin Azshara zu erlangen...", sourceObjectiveStatus = "unverified-source-field" }
quests[38206] = { id = 38206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspektion", description = "Ihr werdet Euch sicher fragen, worum es hier eigentlich geht. Bitte begleitet mich ein Stück.\n\nIch muss ein paar letzte Vorbereitungen treffen, bevor wir die Segel setzen können, und ich weiß, dass Eure Anwesenheit gut für die Moral der Besatzung ist.", sourceObjective = "Begleitet Himmelsadmiralin Rogers und bereitet die Himmelsfeuer auf das Ablegen vor.", progress = "Sobald die Vorbereitungen abgeschlossen sind, machen wir uns auf den Weg nach Sturmheim.", completion = "Kämpft Ihr auf unserer Seite?", sourceObjectiveStatus = "unverified-source-field" }
quests[38207] = { id = 38207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Zeter'el" }
quests[38208] = { id = 38208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Weathered Axe" }
quests[38209] = { id = 38209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Bramblefell" }
quests[38210] = { id = 38210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die uralten Prüfungen", description = "<Während Euch der Rabe in die Augen starrt, dringt eine seltsame Stimme in Euren Geist.>\n\nIch weiß, wer Ihr seid, Champion, und ich weiß, wonach Ihr sucht.\n\nKommt zu mir, wenn Ihr Euch selbst als würdig erachtet.", sourceObjective = "Sucht nach Havi in der Nähe von Aggramars Kammer.", completion = "Ich weiß, dass Ihr viele Fragen habt. Die Antworten erhaltet Ihr beizeiten.\n\nIch bin Havi und ich spreche für die Valarjar, die ruhmreichen Hüter der Hallen der Tapferkeit.\n\nIhr werdet meine Hilfe benötigen, wenn Ihr nach der Aegis sucht. Ja, ich weiß um Eure Pläne, Fremder. Denn ich weiß um viele Dinge...", sourceObjectiveStatus = "unverified-source-field" }
quests[38211] = { id = 38211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Felspark" }
quests[38212] = { id = 38212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brogozog" }
quests[38213] = { id = 38213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Hinweisen", description = "Aktar hat erwähnt, dass er in den Ruinen Sethekk, Oger und sogar Dämonen gesehen hat, aber kein Zeichen von Iskar.\n\nWir werden dort reingehen müssen, wenn wir irgendeinen Hinweis finden wollen, und mir wäre es am liebsten, wenn jemand mit Euren Fähigkeiten die Führung übernehmen würde.\n\nNun, was meint Ihr?", sourceObjective = "Durchsucht die Ruinen von Kra'nak nach Hinweisen.", progress = "Der Einband ist zwar dreckig, doch sind die Seiten immer noch in einem guten Zustand. Unten auf dem Einband steht \"Eigentum von Iskar\".", completion = "Dieser Foliant sieht aus wie der, den Iskar immer bei sich getragen hat. Aus welchem Grund könnte er ihn zurückgelassen haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[38215] = { id = 38215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 015 - Haustvald - ZTO" }
quests[38217] = { id = 38217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tide Behemoth" }
quests[38220] = { id = 38220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arauk Nashal 70:JP3 - Aggramar's Vault - Tracking Quest Cleared - Aggramar's Vault" }
quests[38223] = { id = 38223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg des Dunklen", description = "Ihr überfliegt die Seiten des Folianten. Die meisten sind mit Notizen über die Natur von Schatten und Illusionen bedeckt. Auf der letzten Seite entdeckt Ihr eine Art Tagebuch:\n\nIch suche weiterhin nach einem Heilmittel für den Fluch des Sethe. Wenn Terokk zurückgekommen wäre, würde ich nicht in dieser Situation stecken. Verdammter Reshad!\n\nEin Orc, der sich als Gul'dan vorgestellt hat, hat mich kontaktiert. Er hat ein Heilmittel für diesen Fluch! Ich muss nach Tanaan reisen, und nach dieser \"Litanei\" von ihm suchen.\n\nBringt diese Informationen zu Reshad.", sourceObjective = "Sprecht mit Reshad in den Ruinen von Kra'nak.", progress = "Ich wünschte, es wäre nicht soweit gekommen...", completion = "Danke, {name}.\n\nDas war keine einfache Aufgabe, und ich bin Euch wieder einmal dankbar für Eure Unterstützung. Iskars Wahnsinn muss ein Ende haben.\n\nIch vertraue darauf, dass Ihr bereit sein werdet, wenn die Zeit reif ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[38225] = { id = 38225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod der Hexenmutter!", description = "Die unzähligen Jahre meines Lebens habe ich dem Erlernen und Perfektionieren der Heil- und Regenerationskünste gewidmet.\n\nNichts in der Welt quält mich mehr, als Leben zu nehmen, <Reisender/Reisende>.\n\nUnd darum verurteile ich nur schweren Herzens Magula, die Anführerin der Harpyien, die diesen Hain bedrohen, zum Tode.\n\nMöge ihr Tod das Leben edlerer Lebewesen retten.", sourceObjective = "Tötet Magula.", progress = "Habt Ihr die schreckliche Tat vollbracht, Reisender?", completion = "Möge der Frieden in unseren heiligen Hain zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[38231] = { id = 38231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Shrine Found" }
quests[38232] = { id = 38232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener! Tötet sie!", description = "Gemäß Eurem Vertrag werdet Ihr mir helfen, die Zutaten für ein absolut harmloses Ritual zusammenzutragen.\n\nIch brauche Federn und Hörner. Eine Menge Hörner. Seht Ihr die Schattenrösser, Pirscher und Reiher da drüben in den Olivanhöhen? Die sollten reichlich davon bieten.\n\nOh, und ich brauche Oliven! Jede Menge Oliven. Eine für jeden Finger.\n\nAlso, auf geht's, Helferlein!", sourceObjective = "Erfüllt Euren Vertrag mit Daglop.", progress = "Dieses Land ist reif zur Ernte. Vor allem die Oliven. Die sind wirklich reif. Und ich liebe reife Oliven.", completion = "Lecker! Oliven! Ich liebe diese Dinger. Sie sind der einzig gute Grund, in diese dreckige Welt zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38234] = { id = 38234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Inscribed Ruin Found" }
quests[38235] = { id = 38235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fels in der Brandung", description = "Cenarius benötigt meine Hilfe?\n\nIch werde baldmöglichst aufbrechen, doch ich kann hier nicht fortgehen, solange meine Druiden in Gefahr sind. Ein bösartiger Hexenzirkel von Harpyien ist aufgetaucht und will meinen Hain übernehmen.\n\nDiese Scheusale verbreiten eine versteinernde Krankheit, die alle Befallenen mit der Zeit dahinrafft.\n\nIch möchte natürlich, dass alle meine Anhänger gerettet werden, doch es ist von höchster Bedeutung, dass meine ältesten Schüler überleben, um den Hain in meiner Abwesenheit zu schützen.\n\nWenn Ihr uns helfen möchtet, dann findet meine Schüler und weckt sie aus diesem furchtbaren Zustand auf.", sourceObjective = "Rettet Marnor Lorblatt, Erwind Nebelmoor und Del'thanar Weisenweide.", completion = "Eure Ankunft war ein Segen.\n\nAnde'thoras-ethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[38236] = { id = 38236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Note Found" }
quests[38237] = { id = 38237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das steht so im Vertrag!", description = "Ich muss mein Ritual in einer besonderen Höhle durchführen, die ich am Finsterbundgrabhügel vorbereitet habe.\n\nTrefft mich dort. Dann \"gebe\" ich Euch Eure Belohnung. Hi hi hi.", sourceObjective = "Helft Daglop, sein Ritual auszuführen.", completion = "Gutes Geschäft, oder? Ihr durftet einen Dämon töten, Eure tolle Waffe noch toller machen, und ich werde jetzt der Meister sein. Ein gutes Geschäft für beide Seiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[38238] = { id = 38238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beacher" }
quests[38239] = { id = 38239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Pile" }
quests[38240] = { id = 38240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtzug aktiv" }
quests[38241] = { id = 38241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freigelegte Magie", description = "Kommandant, ich habe Berichte über einen merkwürdigen Stein, der in der Garnisonsmine gefunden wurde. Die Arbeiter sind sich nicht sicher, was es damit auf sich hat, aber ich glaube, er könnte uns noch von Nutzen sein.\n\nWenn Ihr mal wieder bei der Mine seid, könntet Ihr das ja mal näher untersuchen. Und falls es Euch nichts ausmacht, würde ich liebend gern selbst einen Blick auf den Stein werfen.", sourceObjective = "Findet den merkwürdigen Stein bei Eurer Mine.", progress = "Grüße, Kommandant. Habt Ihr den Stein?", completion = "Wie ich es mir gedacht hatte, ein Kampfstein!\n\nIch habe bereits einige ähnliche Steine hier in Draenor gesammelt, aber dieser hier ist wirklich riesig! Ein sehr seltener Fund!", sourceObjectiveStatus = "unverified-source-field" }
quests[38242] = { id = 38242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freigelegte Magie", description = "Kommandant, unsere Arbeiter ham in der Mine was mit starkem Mojo gefunden. Sie sind sich nich' sicher, was es damit auf sich hat, aber vielleicht könntet Ihr mal rübergeh'n und das untersuch'n?\n\nWenn Ihr das Ding habt, bringt es bitte bei mir vorbei, ich würd' gern 'nen Blick drauf werf'n.", sourceObjective = "Findet den merkwürdigen Stein bei Eurer Mine.", progress = "Habt Ihr den Stein, Boss?", completion = "Ich hab' schon einige ähnliche Steine überall in Draenor gefund'n, aber so was Riesiges hatt' ich noch nie!", sourceObjectiveStatus = "unverified-source-field" }
quests[38243] = { id = 38243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für eine Handvoll Erz", progress = "Erz steht auf meinen Handelsrouten derzeit hoch im Kurs und ich versuche meine Vorräte aufzufüllen. Wärt Ihr bereit zu handeln?", completion = "Es war mir ein Vergnügen, mit Euch Geschäfte zu machen." }
quests[38244] = { id = 38244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für ein paar Brocken Erz mehr" }
quests[38246] = { id = 38246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemischer Ruf", description = "Ich habe vorhin den anderen zugehört und kenne jetzt vielleicht den Grund ihrer Angst.\n\nSie sagen, dass der Häuptling ein geheimnisvolles Totem besitzt. Es verleiht ihm Kraft, bringt ihm aber auch beängstigende Visionen.\n\nDieser Wahnsinn wird aufhören, wenn Ihr das Totem zerstört.", sourceObjective = "Zerstört das Alptraumtotem.", completion = "Ich danke Euch, {name}! Mein Neffe ist zu mir zurückgekehrt.\n\nEr berichtet, dass die Quelle des Wahnsinns ein mächtiges Totem inmitten unseres Dorfs sei.\n\nDas ergibt Sinn, aber wer... oder WAS... hat uns so etwas zukommen lassen?\n\nIch werde mich sofort mit den Druiden darüber austauschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38250] = { id = 38250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Ruinen von Kra'nak", description = "Der Schattenrat nimmt die Dienste der Sethekk und anderer machthungriger Arakkoa in Anspruch. Unsere Verbündeten vom Orden der Erwachten haben sie bis zur Ruine im Westen von Tanaan zurückverfolgt. Dort werden sie vom Schattenrat in der Anwendung von Teufelsmagie unterwiesen.\n\nWir müssen sie ausschalten, bevor sie gelernt haben, diese diabolischen Kräfte zu meistern.", sourceObjective = "Greift die Truppen des Schattenrats in den Ruinen von Kra'nak im Tanaandschungel an.", completion = "Willkommen zurück, Kommandant. Unsere Späher haben uns bereits von Euren Erfolgen berichtet.\n\nGut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[38251] = { id = 38251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 013 - Stone Trident" }
quests[38252] = { id = 38252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Ruinen von Kra'nak", description = "Der Schattenrat nimmt die Dienste der Sethekk und anderer machthungriger Arakkoa in Anspruch. Unsere Verbündeten vom Orden der Erwachten haben sie bis zur Ruine im Westen von Tanaan zurückverfolgt. Dort werden sie vom Schattenrat in der Anwendung von Teufelsmagie unterwiesen.\n\nWir müssen sie ausschalten, bevor sie gelernt haben, diese diabolischen Kräfte zu meistern.", sourceObjective = "Greift die Truppen des Schattenrats in den Ruinen von Kra'nak im Tanaandschungel an.", completion = "Willkommen zurück, General. Unsere Späher haben uns bereits von Euren Erfolgen berichtet.\n\nGut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[38253] = { id = 38253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Kriegsrat", description = "Eure Garnison befindet sich in Aufruhr. König Varian Wrynn persönlich ist zu Besuch in Eurer Festung, um über die Invasionspläne für den Tanaandschungel zu sprechen.\n\nDer König und sein gesamtes Gefolge warten auf Euch im Hauptgebäude. Es wäre klug, ihn nicht allzu lange warten zu lassen...", sourceObjective = "Sprecht mit König Varian Wrynn im Hauptgebäude Eurer Garnison.", completion = "<Der König studiert die Karten des Tanaandschungels und der umgebenden Gebiete.>\n\n{name}! Die Allianz ist Euch für die Gründung dieser Garnison zu großem Dank verpflichtet. Dank Eurer Tapferkeit und Eures Führungstalents können wir diesen Krieg hier auf Draenor und nicht inmitten unserer Heimatlande führen.\n\nJetzt ist die Zeit gekommen, diese Sache zu beenden. Seid Ihr bereit für den letzten Feldzug?", sourceObjectiveStatus = "unverified-source-field" }
quests[38254] = { id = 38254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entgleisung", description = "Einige Orcs haben ihre Stimme erhoben, seit Gul'dan die Herrschaft übernommen hat. Und einige von ihnen wurden dafür ins Gefängnis gesteckt. Unter ihnen ist auch eine Ingenieurslegende: Solog Roark, \"Der Eiserne Schiffsbauer\". Er hat sowohl diese Docks als auch die größten Schlachtschiffe der Orcflotte entworfen. Wenn meine Späher richtig liegen, haben sie ihn zurzeit in diesem Gefängniszug eingekerkert... Und möglicherweise ist er bereit, die Seiten zu wechseln!\n\nSammelt Sprengladungen zusammen und trefft Euch mit Yrel beim Zug im Südosten!", sourceObjective = "Sammelt Sprengladungen und einen Zünder.", progress = "Ihr seid es, Kommandant! Naielle hatte versprochen, schon bald jemanden zu schicken.", completion = "Roark ist ganz sicher in diesem Gefängniszug. Aber er ist fest verschlossen. Wir müssen... Oh! Ihr habt Sprengladungen mitgebracht? Naielle denkt ja wirklich an alles! Dann lasst uns jetzt den Waggon aufbrechen und versuchen, diesen Ingenieur davon zu überzeugen, zu uns überzulaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38255] = { id = 38255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugüberfall", description = "Diese Rangari werden den Waggon umstellen und Deckung geben. Aktiviert den Zünder, um die Türen aufzusprengen.\n\nIch werde versuchen, Roark davon zu überzeugen, zu uns überzulaufen. Sein Können im Trockendock ist außergewöhnlich und könnte uns helfen, eine Werft aufzubauen.\n\nAber wenn die Sache nicht funktioniert, müssen wir ihn vielleicht töten. Das Letzte, was wir gebrauchen können, ist jemand, der erneut eine Eiserne Flotte aufbaut...", sourceObjective = "Verwendet den Zünder, um die Tür des Waggons aufzusprengen. Überzeugt dann Roark davon, die Seiten zu wechseln.", completion = "Steckt die Waffe weg. Schwarzfaust ist tot und unser neuer \"Kriegshäuptling\" hat gerade mein Todesurteil unterschrieben. Ich werde wohl von nun an ein Söldner sein.\n\nIhr wollt eine eigene Schiffswerft aufbauen? Dann braucht Ihr meine Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[38256] = { id = 38256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Mann klar zum Meucheln", description = "Ich kann Euch eine Schiffswerft aufbauen. Und das wird nicht so eine selbstgefällige, kindliche Ingenieursfantasie wie dieser Ort hier.\n\nAber dazu benötige ich meine Pläne. Meine Arbeiten wurden konfisziert, als Gul'dan diesen Hafen Admiral Knar übergab.\n\n<Roark spuckt aus.>\n\nGul'dans grünes Gift fließt durch Knars Adern. Von dort oben aus hat er jetzt alles unter Kontrolle. Wir müssen da hoch klettern und ihn ausschalten.", sourceObjective = "Verwendet einen Schwarzfelsgreifer, um auf Knars Bunker zu gelangen. Schaltet ihn aus und nehmt ihm Roarks Werftbaupläne ab.", progress = "Ich werde eine Werft für Euch bauen.", completion = "<Solog Roark wirft einen letzten Blick auf den Hafen.>\n\nAll das haben wir umsonst aufgebaut, {class}. Gul'dan wird sich nehmen, was Eure Truppen nicht zerstört haben.\n\nNächstes Mal werde ich etwas bauen, was von Dauer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[38257] = { id = 38257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffsbauer gesucht", description = "Die Eiserne Horde – oder was auch immer Gul'dan daraus gerade macht – hat sich zurückfallen lassen und den Zugang nach Tanaan gesichert. Ein direkter Angriff würde mit schweren Verlusten einhergehen.\n\nDie Seewege aber sind noch offen. Wenn wir sie gleichzeitig zu Land und zu See angreifen, können wir Gul'dans Horde in die Zange nehmen. {name}, es ist an der Zeit, eine Schiffswerft aufzubauen!\n\nWir müssen die lokalen Ressourcen nutzen. Begebt Euch zu den Eisendocks, wo bereits eine kleine Pioniereinheit der Allianz wartet. Sammelt so viel Ausrüstung zusammen wie Ihr könnt und findet einen Schiffsbauer, der uns eine Flotte aufbauen kann!", sourceObjective = "Begebt Euch zu den Eisendocks und sprecht mit Exarchin Naielle. Der Flugmeister Eurer Garnison kann Euch dorthin bringen.", completion = "Kommandant! Man hatte Euch schon angekündigt. Hier herrscht das reinste Chaos.\n\nMeine Rangari beobachten dieses Gebiet schon seit Eurem ersten Angriff. In den letzten Wochen konnten wir wieder Aktivitäten beobachten, weil die Eiserne Horde auf Gul'dans Befehl hin nach Tanaan flieht.\n\nUnd meine Späher haben etwas erfahren, das Euch interessieren könnte...", sourceObjectiveStatus = "unverified-source-field" }
quests[38258] = { id = 38258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles vergeht", description = "Hier gibt es nichts mehr für mich. Meine alten Klangefährten sind meine Feinde geworden und Gul'dan zieht alles in den Dreck, was noch von meinem Volk übrig ist.\n\nIhr und Eure Gefährten aus Shattrath habt noch genug Courage, um zu kämpfen. Wenn Ihr gelobt, Gul'dan zur Strecke zu bringen, werde ich Euch unterstützen. Ich werde Eure Garnison aufsuchen und zusammen bauen wir eine Schiffswerft auf, mit deren Hilfe wir die roten Meere von Draenor beherrschen werden!\n\nSagt Euren Leuten, dass ich mich auf den Weg mache.", sourceObjective = "Sucht König Varian Wrynn im Hauptgebäude Eurer Garnison auf.", completion = "Ihr habt einen Schiffsbauer gefunden? Sehr gut! Einige Eurer Anhänger können es gar nicht erwarten, in See zu stechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38259] = { id = 38259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Mann an Deck", description = "Dann wollen wir diesen \"Eisernen Schiffsbauer\" mal an die Arbeit gehen lassen, Kommandant. Wenn wir Euren Plan in die Tat umsetzen und Tanaan zeitgleich von Land- und Seeseite aus angreifen wollen, müssen wir so schnell wie möglich ein paar Docks in Betrieb nehmen. Arbeitet mit Roark zusammen und baut eine Schiffswerft für die Allianz auf!\n\nAls ich Roark das letzte Mal sah, befand er sich nordwestlich der Garnison, in der Nähe vom Abendruhhafen.", sourceObjective = "Sammelt Materialien und errichtet eine Werft der Stufe 1 für Eure Garnison.", progress = "Ich brauche Baumaterialien, Kommandant. Man kann keine Docks aus Schlamm bauen.", completion = "<Roark sucht den Horizont mit den Augen ab.>\n\nJa, hier. Diese Naturbucht ist gut geeignet. Aus den Überresten dieses alten Kriegsschiffes könnte man Euer erstes Transportschiff bauen.\n\nWie ich sehe, habt Ihr alle erforderlichen Materialien zusammen. Seid Ihr bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[38262] = { id = 38262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Bilkor the Thrower" }
quests[38263] = { id = 38263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Rogond" }
quests[38264] = { id = 38264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Drivnul" }
quests[38265] = { id = 38265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Dorg" }
quests[38266] = { id = 38266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Zulk" }
quests[38267] = { id = 38267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohe Freunde", description = "Iskar ist verschwunden, und jetzt sitzt uns der Schattenrat an der Kehle. Das muss irgendwie zusammenhängen. Wir müssen den Ort aufsuchen, an dem er zuletzt gesehen wurde: die Ruinen von Kra'nak.\n\nIch habe einen Freund gebeten, in der Nähe ein Lager aufzuschlagen. Ich würde sagen, wir gehen dorthin, um unsere Suche fortzusetzen.", sourceObjective = "Trefft Euch mit Reshad bei Aktars Posten.", completion = "Ah, {name}. Ihr kommt gerade rechtzeitig.\n\nAktar meint, der Schattenrat lehrt die Sethekk seine üblen Pfade. Es gibt sogar eine Gruppe von Hocharakkoa, die jetzt dem Banner des Schattenrats folgen!\n\nIch frage mich, wie Iskar darin verwickelt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[38268] = { id = 38268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkbane" }
quests[38269] = { id = 38269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohe Freunde", description = "Iskar ist verschwunden, und jetzt sitzt uns der Schattenrat an der Kehle. Das muss irgendwie zusammenhängen. Wir müssen den Ort aufsuchen, an dem er zuletzt gesehen wurde: die Ruinen von Kra'nak.\n\nIch habe einen Freund gebeten, in der Nähe ein Lager aufzuschlagen. Ich würde sagen, wir gehen dorthin, um unsere Suche fortzusetzen.", sourceObjective = "Trefft Euch mit Reshad bei Aktars Posten.", completion = "Ah, {name}. Ihr kommt gerade rechtzeitig.\n\nAktar meint, der Schattenrat lehrt die Sethekk seine üblen Pfade. Es gibt sogar eine Gruppe von Hocharakkoa, die jetzt dem Banner des Schattenrats folgen!\n\nIch frage mich, wie Iskar darin verwickelt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[38270] = { id = 38270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach dem Jäger", description = "Mit dieser Karte kennen wir den genauen Ursprung der Angriffe. Es wird Zeit, dass wir herausfinden, wer oder was hinter diesen Angriffen steckt und ob es sich um einen potenziellen Verbündeten handelt.", sourceObjective = "Sucht den Jäger des Blutenden Auges in der Nähe von Zeth'Gol.\n\nBereitgestellter Gegenstand:", completion = "Ihr... erinnert Euch an mich? Ich kam mit Euch durch das Portal. Mein Name war... Ariok... bevor ich zu dem hier wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[38271] = { id = 38271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf blutigen Pfaden", description = "Meine Opfer... Sie sprechen von einer Höhle. Einer dem Blutenden Auge geweihten Höhle. Kilrogg könnte dort sein... Ich breche auf.", sourceObjective = "Folgt Ariok zur Höhle.", completion = "Alte Erde... altes Blut. Ich rieche Kilrogg. Er war hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[38272] = { id = 38272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blutende Auge", description = "Die Höhle zerrt an mir. Sie hält wütende Geister in der Nähe. Kilrogg hat hier seine Magie gewirkt. Ihr werdet mir helfen, alles zu verstehen...", sourceObjective = "Erreicht die unterste Ebene des Blutenden Auges.", completion = "Ihr betretet heiligen Boden, Eindringling. Hier haben die Häuptlinge des Blutenden Auges Rituale durchgeführt, um in die Zukunft zu blicken.\n\nIhr solltet sterben, aber es steht viel auf dem Spiel...", sourceObjectiveStatus = "unverified-source-field" }
quests[38273] = { id = 38273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister des Blutenden Auges", description = "Offensichtlich wird die Höhle von mächtigen Geistern bewacht, von Ahnen des Blutenden Auges.\n\nWas auch immer dort unten ist, wird leichter zu besiegen sein, wenn Ihr Euch vorher eines Großteils der Geister entledigt.", sourceObjective = "Tötet 6 wütende Blutgeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[38274] = { id = 38274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Kilrogg", description = "Wenn Ihr wissen wollt, was Kilrogg und sein neuer Meister vorhaben, werdet Ihr sein Auge brauchen. Nach dem Ritual stellen alle Häuptlinge ihr Auge unter den Schutz der Geister des Blutenden Auges in der nächsten Kammer.\n\nGeht und durchsucht das Gewölbe nach dem Auge von Kilrogg. Die anderen Häuptlinge werden sich uns entgegenstellen und Euch bekämpfen.\n\nPlatziert dann das Auge auf dem rituellen Zeichen in der Nähe, um Eure Antworten zu erhalten.", sourceObjective = "Sucht nach dem Auge von Kilrogg und führt das Seherritual durch.", progress = "Was habt Ihr erfahren?", completion = "Pah, Kilrogg ist nicht hier, nur Omen und Warnungen. Das ist Euer Pfad, {name}. Meiner führt zur Vernichtung von Kilrogg...", sourceObjectiveStatus = "unverified-source-field" }
quests[38275] = { id = 38275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Return to Firelands 1 Mission Completed" }
quests[38276] = { id = 38276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.1 Garrison - World Boss Invasion Loot" }
