quests[38283] = { id = 38283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Stolen Captain's Chest" }
quests[38286] = { id = 38286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Azsharas Zorn", description = "{name}, Kriegsherr Parjesh hat sich in den magischen Vortex gleich da vorne gestürzt. Er ist zu einer Insel vor der Küste im Südosten zurückgekehrt, wo Königin Azshara weitere Truppen zusammenzieht.\n\nDie Königin schäumt vor Wut, dass wir uns ihr entgegenstellen. Sie beschwört gerade eine Monstrosität, die als ihr Zorn bekannt ist, um uns für unseren Widerstand zu strafen und die Verheerten Inseln untergehen zu lassen.\n\nIhr müsst Azsharas Zorn besiegen, bevor die Königin ihn entfesselt und uns alle vernichtet!", sourceObjective = "Begebt Euch in das Auge Azsharas und besiegt dann Kriegsherr Parjesh und Azsharas Zorn. das Auge Azsharas ist ein Dungeon. Ihr solltet also lieber ein paar Freunde auf diese gefährliche Unternehmung mitnehmen.", completion = "<Golganneths Gezeitenstein steht unversehrt und ungeschützt da.>", sourceObjectiveStatus = "unverified-source-field" }
quests[38287] = { id = 38287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohes Tierleder", progress = "Rohes Tierleder steht auf meinen Handelsrouten derzeit hoch im Kurs und ich versuche meine Vorräte zu füllen. Wärt Ihr bereit, zu handeln?", completion = "Es war mir ein Vergnügen, mit Euch Geschäfte zu machen." }
