quests[38297] = { id = 38297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräuter im Übermaß" }
quests[38299] = { id = 38299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschöpfe von Draenor", description = "Ich bin immer auf der Suche nach neuen Haustieren für meine Sammlung und hier in Draenor habe ich schon einige ungewöhnliche Haustiere ergattert. Was haltet Ihr von einem Haustierkampf? Wenn Ihr mein bescheidenes Team besiegt, lernen wir beide vielleicht ein paar neue Tricks.", sourceObjective = "Besiegt Erris die Sammlerin in einem Haustierkampf.", completion = "Gar nicht schlecht. Kommt vorbei, wenn ich mal wieder in der Nähe bin, vielleicht hab ich ein paar neue Haustiere für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[38300] = { id = 38300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschöpfe von Draenor", description = "Ich bin immer auf der Suche nach neuen Haustieren für meine Sammlung und hier in Draenor habe ich schon einige ungewöhnliche Haustiere ergattert. Was haltet Ihr von einem Haustierkampf? Wenn Ihr mein bescheidenes Team besiegt, lernen wir beide vielleicht ein paar neue Tricks.", sourceObjective = "Besiegt Kura Donnerhuf in einem Haustierkampf.", progress = "Und, wie sieht's nun aus mit einem Kampf?", completion = "Gar nicht schlecht. Kommt vorbei, wenn ich mal wieder in der Nähe bin, vielleicht hab ich ein paar neue Haustiere für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[38304] = { id = 38304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'sharah", sourceObjective = "Sprecht mit Malfurion Sturmgrimm bei Lorlathil in Val'sharah.", sourceObjectiveStatus = "unverified-source-field" }
quests[38305] = { id = 38305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarius, Hüter des Hains", description = "Ich grüße Euch, <Held/Heldin>.\n\nWillkommen in Val'sharah. Es ist schon lange her, dass ich einen Fuß in diese edlen Wälder gesetzt habe. Viel zu lange...\n\nUnsere Aufgabe hier ist einfach. Wir müssen meinen Mentor, Cenarius, rufen und herausfinden, wo er die Tränen von Elune verwahrt. Sie werden Euch unserem Ziel näher bringen, Sargeras' Grab zu versiegeln und die Legion aufzuhalten.\n\nAuf Euch warten schwere Prüfungen. Euer Aufenthalt hier ist lediglich eine Atempause von kurzer Dauer.\n\nKommt, das wird nicht viel Zeit in Anspruch nehmen.", sourceObjective = "Sprecht mit Malfurion Sturmgrimm bei Lorlathil in Val'sharah.", sourceObjectiveStatus = "unverified-source-field" }
quests[38306] = { id = 38306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das geheimnisvolle Notizbuch", description = "Dieses Buch hat schon bessere Zeiten gesehen. Auf den aufgequollenen und von wilden Tieren zerfetzten Seiten lässt sich nicht mehr viel lesen außer ein paar poetischen Ergüssen über das \"herrliche Leuchten\" der Unterstadt und eine gewisse Estelle Gendry.", sourceObjective = "Bringt das Notizbuch zu Estelle Gendry in Unterstadt zurück.", completion = "<Estelle blättert durch das beschädigte Buch und seufzt wehmütig.>\n\nHerrje, ein weiterer Geliebter, der das Zeitliche gesegnet hat! Draenor hat die fürchterliche Angewohnheit, meine Liebhaber bei lebendigem Leibe zu verschlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38307] = { id = 38307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bitte des Kriegshäuptlings", sourceObjective = "Lest die Königliche Vorladung und folgt Nathanos Pestrufer durch das Portal nach Durotar.", progress = "Wenn sie doch nur nicht darauf bestanden hätte, Euch unversehrt zu ihr zu bringen...", completion = "Zufrieden?", sourceObjectiveStatus = "unverified-source-field" }
quests[38308] = { id = 38308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen in der Warte", description = "Fallschirmeinheiten der Allianz sind von der Himmelsfeuer abgesprungen und bei der Schwarzschnabelwarte gelandet.\n\nWährend des Überfluges konnte ich ihre Anzahl und Positionen zwar nicht bestimmen, aber ich habe ihre Fallschirme in den Bäumen und EINE MENGE Rabenbären am Boden gesehen.\n\nWenn sie noch da oben sind, verstecken sie sich dort und behalten uns im Auge.\n\nIch habe einen Reiter über der Warte als Wache abgestellt, während ich weiter nach Sturmheim eile.\n\n- Liza Cullen, Schreckensreiterin, 1. Geschwader", sourceObjective = "Sichert die Geheimdienstinformationen des SI:7 von Meisterspion Kloppfeifer an der Schwarzschnabelwarte.", sourceObjectiveStatus = "unverified-source-field" }
quests[38309] = { id = 38309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Content Perk: The Light Reveals" }
quests[38310] = { id = 38310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Content Perk: Righteous Strength" }
quests[38311] = { id = 38311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Content Perk: Call of the Highlord" }
quests[38312] = { id = 38312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifhaken abgreifen", description = "Diese Prüfungen werden uns also die Aegis beschaffen, und die nächste befindet sich oben auf diesem Berg? Das könnte ein Problem darstellen.\n\nDer einzige Weg hinauf auf den Berg führt geradewegs durch die Stadt der Vrykul, und deren Tore sind fest verschlossen. Doch mit Greifhaken könnten wir es hinüberschaffen. Ich habe einem der Vrykul diesen Werfer abgenommen, falls Ihr keinen habt.\n\nIch werde vorausgehen und mich ein wenig umsehen, wo der beste Platz ist, um hochzuklettern.", sourceObjective = "Nehmt den sturmgeschmiedeten Greifhakenwerfer und trefft Euch mit Lorna Crowley außerhalb der Mauern von Hrydshal.", completion = "Damit sollte es funktionieren.\n\nUnd jetzt rein da, bevor sie uns entdecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[38314] = { id = 38314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Hidden Demon" }
quests[38316] = { id = 38316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 014 - Fel Collector" }
quests[38317] = { id = 38317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Tarnung", description = "<Ihr überfliegt Kloppfeifers Bericht.>\n\nMein Fallschirm ist von einem Schrapnell beschädigt worden, und ich habe eine harte Landung in einem Rabenbärennest hingelegt. Zum Glück haben ein paar Eier meinen Sturz abgefangen.\n\nIllandris und Shwayder habe ich aus den Augen verloren. Sie sind beide Meister der Tarnung, und ich bin mir sicher, dass man sie nicht entdecken wird.\n\nIch werde weiterhin die feindlichen Aktivitäten beobachten. Ich muss nur noch das ganze Eigelb von meinem Tarngerät entfernen. Ich hoffe, die Mutter treibt sich nicht hier herum...", sourceObjective = "Schaltet Meisterspionin Illandris und Meisterspion Shwayder aus.", progress = "Wir können hier nicht frei sprechen... Die Allianz hat ihre Augen und Ohren überall in diesen Hügeln.", completion = "Endlich geht's wieder ins Gefecht!", sourceObjectiveStatus = "unverified-source-field" }
quests[38318] = { id = 38318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer braucht schon Flügel?", description = "Mithilfe dieses Hakenwerfers sollten wir jetzt die Stadt infiltrieren können. Auf der Mauer hinter uns scheint es eine gut geeignete Stelle für den Haken zu geben. Dort auf dem Grat befindet sich ein Aussichtspunkt.\n\nSobald wir drin sind, versuche ich, mich an den Wachen vorbeizuschleichen und einen Blick auf den Bergpfad zu werfen. Ich würde es sehr zu schätzen wissen, wenn Ihr für etwas Ablenkung sorgen könntet. Wenn alles gut geht, treffen wir uns im oberen Teil der Stadt.\n\nViel Glück!", sourceObjective = "Begebt Euch auf den Grat hinauf und verwendet den sturmgeschmiedeten Greifhakenwerfer, um die Mauern von Hrydshal zu erklimmen.", completion = "Ihr hättet die Gesichter dieser Vrykul sehen sollen, als Ihr über die Mauer gesegelt kamt! \n\nDieser Hakenwerfer könnte sich noch an vielen Orten als nützlich erweisen. Ihr solltet ihn behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[38320] = { id = 38320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: The Blade of Kra'nak" }
quests[38322] = { id = 38322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Hain", description = "Jetzt wo mein Hain sicher ist, kann ich mich um die von Euch erwähnte Bedrohung kümmern.\n\nUnd es ist in der Tat bestürzend, von Cenarius' misslicher Lage zu hören. Sagt Malfurion, dass wir uns im Hain treffen werden.", sourceObjective = "Kehrt zu Malfurion Sturmgrimm im Hain des Cenarius in Val'sharah zurück.", completion = "Wunderbar. Die Erzdruiden haben sich bereits versammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[38323] = { id = 38323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Hain", description = "Vergebt mir, {race}. Der Tod von Erzdruide Mondklaue ist in der Tat ein harter Schlag...\n\nWir müssen Malfurion davon berichten. Erzählt ihm von Thaons Schicksal und Xavius' Rückkehr.\n\nUnd beeilt Euch. Ich fürchte, dass dies die größte Bedrohung sein könnte, mit der Val'sharah je konfrontiert wurde.", sourceObjective = "Kehrt zu Malfurion Sturmgrimm im Hain des Cenarius in Val'sharah zurück.", completion = "Der Verlust von Thaon schmerzt uns sehr. Wir waren zwar nicht immer einer Meinung, aber er war ein großer Druide und ein wahrer Beschützer des Tals.\n\nXavius wird für seinen Tod bezahlen...", sourceObjectiveStatus = "unverified-source-field" }
quests[38324] = { id = 38324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Accessoires der Verfluchten", description = "Moment! Bevor Ihr losstürzt, brauchen wir noch mehr als nur ein bisschen Seetang. \n\nDie Vrykul laufen doch immer mit diesen Knochen herum. Sie tragen sie wie eine Art Schmuck. Wenn Ihr ein paar davon einsammeln könnt, würde ich damit die Verkleidung noch etwas verbessern.\n\nAlso, worauf wartet Ihr noch?", sourceObjective = "Sammelt 8 verfluchte Knochen in Helheim.", progress = "Sammelt genug Knochen ein, bevor wir weiterziehen.", completion = "Ja, die sind gut.\n\nUnd jetzt wollen wir doch mal sehen, ob wir den alten Guarm nicht reinlegen können, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[38331] = { id = 38331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Havis Test", description = "Gleich bei Eurem Eintreffen in diesem Land konnte ich Eure Macht spüren. Ihr verfolgt ein großes Ziel und tragt eine schwere Bürde.\n\nDie Aegis von Aggramar wird in den heiligen Hallen des allmächtigen Vaters verwahrt. Nur wenn Ihr Eure Tapferkeit unter Beweis stellt, könnt Ihr sie vor Euren Feinden beanspruchen.\n\nDazu müsst Ihr viele Prüfungen bestehen, aber zunächst muss ich mich Eurer Stärke vergewissern. Mein Eintopf ist noch nicht fertig und meine alten Knochen können die Zutaten nicht den Hügel hinaufschleppen.\n\nIhr seht so aus, als ob Ihr starke Arme habt. Würdet Ihr einem alten Mann helfen, seinen Eintopf fertig zu kochen?", sourceObjective = "Werft Zutaten aus dem Korb voller Wurzelgemüse, dem Fass mit Krabben und herzhaftes Vrykulgetreide in Havis Eintopf.", progress = "Riecht gut, nicht wahr?", completion = "Hah, Ihr werft wie eine Schildmaid!\n\nWie bitte? Das ist ein Kompliment!\n\nKostet den Eintopf, junger Champion, und genießt den Geschmack der guten Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[38332] = { id = 38332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Waldläuferlord", description = "Schön, dass Ihr das Gemetzel beim Wrack überlebt habt. Nathanos hat es auch geschafft, aber jetzt ist sein Gesicht noch hässlicher als vorher.\n\nEr ist mit einer Gruppe Waldläufer nach Norden gegangen, um nach Sylvanas zu suchen. Seit dem Kampf hat sie niemand mehr gesehen.\n\nEr lässt ausrichten, dass Ihr ihm folgen sollt, wenn Ihr wieder auf den Beinen seid.", sourceObjective = "Meldet Euch bei Nathanos Pestrufer.", completion = "<Nathanos' Augen verengen sich, als er das Wrack von Sylvanas' Schiff erblickt.>\n\nSie ist irgendwo da draußen... Sie muss dort irgendwo sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[38333] = { id = 38333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Drake Wrestler" }
quests[38334] = { id = 38334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Jewel of Hellfire" }
quests[38337] = { id = 38337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuppe um Schuppe", description = "Die Vrykul in dieser Gegend scheinen ihre Rüstungen aus den Schuppen dieser Drachen herzustellen. \n\nWenn Ihr genug Material von den hiesigen Drachen zusammenbekommt, könnt Ihr vielleicht etwas Nützliches daraus machen.", sourceObjective = "Sammelt Sturmdrachenschuppen von den Sturmdrachen in Hrydshal ein.", progress = "Oh, was habt Ihr denn da?", completion = "Es war eine gute Idee, diese Schuppen zu sammeln.\n\nDaraus lässt sich mit Sicherheit eine solide Rüstung herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38339] = { id = 38339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Hilfe von guten Feinden", description = "Ich weiß nicht, was Ihr hier macht, aber ich möchte Euch danken. Wenn Ihr aber noch weiter wollt, müsst Ihr an diesem Höllenhund, Guarm, vorbei.\n\nIch habe das selbst schon ein paar Mal versucht und ich glaube, ich kenne eine Möglichkeit. Wir könnten diesen Kvaldir ein bisschen Seetang abnehmen, um Guarm zu täuschen. Er ist zwar sehr bösartig, aber nicht sehr klug.\n\nWas meint Ihr? Könntet Ihr es mit ein paar Kvaldir aufnehmen?", sourceObjective = "Sammelt 20 Bündel Seetang von den Nebelrufern und Seelenschindern der Kvaldir in Helheim ein.", progress = "Habt Ihr genug für eine geeignete Verkleidung?", completion = "Was?! Wie viele Kvaldir habt Ihr getötet? Ihr seid stärker, als ich dachte, Fremder!\n\nWenn wir erst an ihrem Hund vorbei sind, bin ich mir sicher, dass Helya sehen wird, dass weder Ihr noch ich hierher gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[38342] = { id = 38342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein anderer Weg", description = "Tja, die Brücke ist keine Option mehr. Habt Ihr immer noch diesen Greifhakenwerfer bei Euch?\n\nVielleicht kommen wir von der Spitze dieses Turms aus da rüber. Dazu müssen wir aber erst mal mit dem großen, hässlichen Kerl davor fertigwerden.\n\nIhr geht voran.", sourceObjective = "Besiegt Gunnlaug Schuppenherz in Hrydshal und steigt dann zur Spitze des Turms hinauf.", progress = "So weit, so gut...", completion = "Ihr lasst Euch nicht so leicht aufhalten, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[38343] = { id = 38343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht keinen Hel daraus" }
quests[38344] = { id = 38344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das geheimnisvolle Notizbuch", description = "Dieses Buch hat schon bessere Zeiten gesehen. Auf den aufgequollenen und von wilden Tieren zerfetzten Seiten lässt sich nicht mehr viel lesen, aber Ihr könnt etwas entziffern, das aussieht wie die Ergebnisse eines Trinkspiel aus Eisenschmiede. Ein Zwerg namens Krom Starkarm steht in der Wertung ganz oben.", sourceObjective = "Bringt das Notizbuch zu Krom Starkarm in Eisenschmiede zurück.", completion = "Oho, da werden Erinnerungen wach. Ihr habt nicht zufällig einen Blick auf die Ergebnisse geworfen, oder?\n\nDas hat mal Nolan gehört, möge er in Frieden ruh'n. Als Forscher hat er nicht viel getaugt, aber trinken konnte er wie kein Zweiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[38345] = { id = 38345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münzkunde", description = "Ich hasse es, düstere Stimmung zu verbreiten, aber ich glaube nicht, dass wir Nolan in einem Stück finden. Oder in Einzelteilen.\n\nNolan war ein begeisterter Schatzjäger. Er reiste von einem Ende der Welt zum anderen auf der Suche nach seltenen Münzen. Es sieht ganz so aus, als hätte ihn die Jagd nach einigen gut erhaltenen draenischen Münzen das Leben gekostet. Hört zu: Ich zeige Euch, wie diese Münzen aussehen und Ihr bringt mir ein paar mehr davon, dann können wir ihm zu Ehren eine Ausstellung organisieren.", sourceObjective = "Bringt Krom Starkarm in Eisenschmiede fehlgeprägte draenische Münzen. Ihr könnt fehlgeprägte draenische Münzen beim Abschluss Eures ersten zufälligen heroischen Draenordungeons des Tages erhalten.", progress = "Wie läuft die Schatzjagd?", completion = "Das sind wirklich gut erhaltene Stücke. Nolan wäre jetzt grün vor Neid.", sourceObjectiveStatus = "unverified-source-field" }
quests[38346] = { id = 38346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münzkunde", description = "Ich hatte ihm doch gesagt, dass er in sein Verderben läuft! Und das alles wegen ein paar lächerlichen Münzen! Nun gut, neue Liebhaber gibt es ja wie Sand am Meer.\n\nFür die Zwischenzeit sollst du mir reichen. Bist ja auch von der hübschen Sorte, nicht wahr? Sei ein Schatz und bring mir noch ein paar mehr von diesen Münzen. Ich benötige sie für... weitere Untersuchungen.", sourceObjective = "Bringt Estelle Gendry in Unterstadt fehlgeprägte draenische Münzen. Ihr könnt fehlgeprägte draenische Münzen beim Abschluss Eures ersten zufälligen heroischen Draenordungeons des Tages erhalten.", progress = "Und? Habt Ihr die Münzen, um die ich Euch gebeten habe?", completion = "Wie reizend von dir. Ich wusste doch, auf dich ist Verlass, Zuckerschnecke.\n\nHmmm, irgendetwas ist merkwürdig an diesen Münzen...", sourceObjectiveStatus = "unverified-source-field" }
quests[38347] = { id = 38347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seetang tarnt besser", description = "So, die Verkleidung ist fertig!\n\nUnd der Gestank ist ein Teil davon. Es ist wahrscheinlich am besten, wenn wir auch so riechen wie die Kvaldir. Aber ich befürchte, dass ich einen Priester brauchen werde, um diesen Gestank hinterher wieder loszuwerden.", sourceObjective = "Benutzt die Kvaldirverkleidung, um an Guarm vorbeizuschleichen.", progress = "Dieser Gestank ist wirklich unglaublich!\n\nIch hoffe, dass die Verkleidung wenigstens funktioniert!", completion = "Das war aber wirklich widerlich, Fremder! Selbst bei den Toten habe ich noch nie einen so abstoßenden Gestank feststellen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38348] = { id = 38348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlock \"Silvermoon\"" }
quests[38351] = { id = 38351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal fürs Handgepäck", description = "Meine Gehilfen haben herausgefunden, wie sich Ogerportalsteine in brauchbare Gegenstände für unsere Garnison umwandeln lassen. Sprecht mit Varsha draußen, um Euren ersten Arbeitsauftrag zu starten.", sourceObjective = "Sprecht mit Varsha vor dem Geisterhaus.", completion = "Wie ich sehe, habt Ihr Varsha gefunden. Bringt ihr regelmäßig Portalsteine. Das könnte uns gegenüber der Eisernen Horde einen entscheidenden Vorteil verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38352] = { id = 38352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kazrok" }
quests[38354] = { id = 38354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal fürs Handgepäck", description = "Meine Gehilfen haben herausgefunden, wie sich Ogerportalsteine in brauchbare Dinge für unsere Garnison umwandeln lassen. Sprecht mit Lehrling Var'nath draußen, um Euren ersten Arbeitsauftrag zu starten.", sourceObjective = "Sprecht mit Lehrling Var'nath vor dem Magierturm.", completion = "Wie ich sehe, habt Ihr Lehrling Var'nath gefunden. Bringt ihm regelmäßig Portalsteine. Das könnte uns gegenüber der Eisernen Horde einen entscheidenden Vorteil verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[38355] = { id = 38355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 002 - Moonrest Shore - twh" }
quests[38356] = { id = 38356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen Bass", description = "Es ist so ruhig, jetzt, wo unsere Garnison ausnahmsweise mal nicht von feindlichen Truppen belagert wird.\n\nGut, dass Ihr mich habt, Kommandant! Ich weiß, wie wir ein bisschen Leben in die Bude bringen und gleichzeitig die Moral unserer Leute stärken.\n\nBesorgt mir ein paar Sachen aus ganz Draenor, und ich erfülle Eure Garnison mit Musik. Ich würde sogar ein paar Musikrollen aus meiner eigenen Sammlung beisteuern!\n\nWas sagt Ihr dazu?", progress = "Besorgt einen Bass-Blaster, ein Laz-Tron-Laufwerk, einen phonischen Verstärker, einen F.N.K.-Kondensator und einen Klafter uraltes Holz.", completion = "Ist das das Beste, was Draenor zu bieten hat? Ihr habt Glück, dass ich auf einer Ingenieursschule war. Der Garni-Blaster 5000 ist im Handumdrehen fertig!" }
quests[38357] = { id = 38357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mögliche Nebenwirkungen: leichtes Untotsein", description = "Die Effekte dieses \"Nebenprodukts\" sind recht drastisch.\n\nAufgrund der rapiden Zellendegeneration werden die Subjekte blitzschnell in willenlose Hüllen verwandelt, die nur noch von blindem Hass auf alles Lebende angetrieben werden.\n\nWie Ihr Euch sicher vorstellen könnt, hat die lokale Fauna einigen Schaden genommen. Oh, und auch der Großteil der Besatzung...\n\nAuf jeden Fall wünsche ich Euch viel Glück!", sourceObjective = "Tötet 10 instabile Bären oder Seemänner.", progress = "Was denn? Ihr wollt sie doch nicht in diesem Zustand belassen? Habt Ihr denn gar kein Mitleid?\n\nWie wäre es mit Geld? Ihr mögt doch Geld, oder?", completion = "Die K.A.V. verhält sich absolut human.", sourceObjectiveStatus = "unverified-source-field" }
quests[38358] = { id = 38358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer rein damit", description = "Die Schwarze Rose war ein mobiles Marinelabor der Königlichen Apothekervereinigung. Und natürlich hatten wir auch ein paar... instabile \"Nebenprodukte\" an Bord.\n\nBedauerlicherweise ist eine dieser Substanzen während des Gefechtes mit dem Allianzschlachtschiff über Bord gegangen. Und es hat die Küste ganz schön hart getroffen.\n\nDie K.A.V. muss sich darum kümmern, bevor wir weiter ins Inland drängen.\n\nBitte nehmt Euch einen Sicherheitsbehälter und füllt ihn auf. Dann werden wir uns später um die korrekte Entsorgung kümmern.", sourceObjective = "Füllt den Sicherheitsbehälter mit instabilem Abfall.", progress = "Der Sicherheitsbehälter ist noch nicht voll.", completion = "Sehr schön, stellt das einfach irgendwo ab. Und bloß nichts davon verschütten!\n\n<Die Apothekerin kichert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[38359] = { id = 38359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 003 - Lorlathil - twh" }
quests[38360] = { id = 38360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Windläufer", description = "Sylvanas zu finden, hat jetzt oberste Priorität!\n\nWir können einen größeren Suchbereich abdecken, wenn wir uns aufteilen. Ich werde mit einem Team in die Hügel über dem Lager der Feinde gehen, und Ihr untersucht das Wrack selbst nach Anzeichen der Besatzung.\n\nWenn wir da oben fertig sind, treffen wir uns am anderen Ende des Strandes.", sourceObjective = "Sucht am Wrack der Windläufer und an der nahe gelegenen Küste nach Anzeichen auf Sylvanas.", completion = "Dann ist sie also doch entkommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[38361] = { id = 38361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des Pestrufers", description = "An diesem Brocken werden sich die Allianzhunde verschlucken. Sie haben die Bansheekönigin angegriffen und sich den Zorn ihres Champions zugezogen!\n\nGenau wie meine Bogeneinheiten, Axtkämpfer und Höllenhunde werdet Ihr ein Werkzeug meiner Rache sein. Ich will, dass Ihr Leichenberge hinterlasst, {class}. Und ich werde das Gleiche tun. Wenn wir uns wiedertreffen, will ich Blut an Euren Händen sehen.", sourceObjective = "Tötet 15 Fallschirmjäger der 7. Legion oder Greifenreiter der Himmelsfeuer.", progress = "Mit Weicheiern kann ich nichts anfangen. Verschwindet, wenn Ihr nicht bereit seid, Rache zu üben!", completion = "Für diese Unverfrorenheit werden sie noch lange zahlen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[38362] = { id = 38362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausame Trophäe", description = "Es hat den Anschein, dass Sylvanas nicht will, dass man ihr folgt... weder wir noch andere.\n\nUnd ihr Wille zählt. Ich habe ihn nicht zu hinterfragen, sondern ihm nur zu gehorchen.\n\nIn diesen nahe gelegenen Hügeln bereitet sich gerade ein Greifenmeister auf den Abflug vor. Ich gehe davon aus, dass er die Königin aus der Luft suchen will. Meine Waldläufer sind schon in Stellung gegangen. Sie warten nur noch auf den richtigen Moment.\n\nWenn dieser Auftrag erledigt ist, will ich seinen Kopf als Trophäe.", sourceObjective = "Schlagt Than Sturmhimmel den Kopf ab.", progress = "Habt Ihr seinen Kopf?", completion = "Seht Euch diesen Kopf genau an, {name}. Das passiert, wenn man sich den Verlassenen entgegenstellt.\n\nVorerst sollten wir uns auf die Suche nach der Aegis von Aggramar machen. Ich werde ein paar Späher aussenden, um ihren Standort in Erfahrung zu bringen. Auch Ihr solltet Euch auf die Suche machen.\n\nWorauf wartet Ihr noch?", sourceObjectiveStatus = "unverified-source-field" }
