quests[38374] = { id = 38374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Drekirjar" }
quests[38376] = { id = 38376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem Hochlord", description = "Tirion schwindet an dieser teuflischen Küste immer mehr dahin... und der Aschenbringer mit ihm! Wir dürfen keine Zeit mehr verschwenden.\n\nSagt einfach Bescheid, wenn Ihr aufbrechen wollt. Wir sind bereit.", sourceObjective = "Findet Tirion Fordring und den Aschenbringer an der Verheerten Küste und bringt sie in Sicherheit.", completion = "Euch verdanke ich mein Leben, {name}. Wie wir alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[38377] = { id = 38377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Smaragdkönigin", description = "{name}, Ihr seid zurück! Das ist gut.\n\nIch habe mich mit den anderen Erzdruiden besprochen und wir stimmen überein, dass Cenarius' gegenwärtiger Zustand nur das Symptom eines viel größeren Problems ist. Eure Erfahrungen im Mondklauental bestätigen das.\n\nWir brauchen Hilfe.\n\nEs gibt nur eine Person, die Licht in das Dunkel dieser Ereignisse bringen kann. Da Thaon tot ist, müssen wir Euch um Hilfe dabei bitten, die Herrin der Träume zu kontaktieren.", sourceObjective = "Sprecht mit Malfurion, wenn Ihr bereit seid.", completion = "Seht! Ysera, die Smaragdkönigin.", sourceObjectiveStatus = "unverified-source-field" }
quests[38380] = { id = 38380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Hivequeen Zsala" }
quests[38381] = { id = 38381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide der Lehren", description = "Elothir lebt im Einklang mit der Natur im uralten Hain Thas'talah und unterrichtet seine Akolythen in den Künsten des Heilens und im Bewahren der Lehren.\n\nSucht ihn auf und teilt ihm mit, dass er hier dringend benötigt wird.", sourceObjective = "Sucht Elothir in Thas'talah auf.", completion = "Willkommen, Reisender.", sourceObjectiveStatus = "unverified-source-field" }
quests[38382] = { id = 38382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide des Tals", description = "Tief in unserem Wald verborgen liegt das Mondklauental.\n\nDort findet Ihr eine zurückgezogene Gruppe wilder Druiden, die damit beauftragt sind, Val'sharah vor allem zu beschützen, was den Einklang der Natur stören könnte.\n\nDer Anführer dieser Druiden ist Thaon Mondklaue, der entschlossenste Kämpfer der Erzdruiden.\n\nSucht ihn auf und teilt ihm mit, dass Cenarius seine Hilfe benötigt.", sourceObjective = "Sprecht mit Thaon Mondklaue.", completion = "Ich werde Cenarius helfen, sobald mein Hain wieder sicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[38383] = { id = 38383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 019 - Helheim - ZTO" }
